  const escape=text=>text.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
  const replaceTerm=(value,from,to)=>{const single=/^[\p{L}]+$/u.test(from),pattern=single?`(?<![\\p{L}\\p{N}_@.])${escape(from)}(?![\\p{L}\\p{N}_@.])`:escape(from);return value.replace(new RegExp(pattern,'giu'),to)};
