  function apply(root=document.body){if(!root)return;const selected=activeTerms(),walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT),nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);nodes.forEach(node=>{const original=node.nodeValue;let value=original;selected.forEach(([from,to])=>value=replaceTerm(value,from,to));if(value!==original)node.nodeValue=value});document.querySelectorAll('[placeholder],[title],[aria-label]').forEach(element=>{['placeholder','title','aria-label'].forEach(attribute=>{let original=element.getAttribute(attribute);if(!original)return;let value=original;selected.forEach(([from,to])=>value=replaceTerm(value,from,to));if(value!==original)element.setAttribute(attribute,value)})})}
